class serieActions extends sfActions
{
  public function preExecute()
  {    
    $isAuthenticated = $this->getUser()->isAuthenticated();
    $base_path = sfConfig::get('base_simad');
    if(!$isAuthenticated){
      $this->redirect($base_path."/backend.php/security/login");
    }
  }
  
  public function executeIndex()
  {
    return $this->forward('serie', 'list');
  }

  public function executeConsulta()
  {
  	$this->dependencia_id = $this->getRequestParameter('dependencia_id');
  }	
  public function executeList()
  {
  	$parametros_consulta = "";
  	
    
    $c=new Criteria();
	
	$this->dependencia_id = $this->getRequestParameter('dependencia_id');
	if($this->dependencia_id != ""){
		$c->add(SeriePeer::DEPENDENCIA_ID, $this->dependencia_id);
		$parametros_consulta .= "&dependencia_id=".$this->dependencia_id;
	}
	
	if($this->getRequestParameter('codSerie')){
		$c->add(SeriePeer::CODIGO, '%'.$this->getRequestParameter('codSerie').'%',Criteria::LIKE);
		$parametros_consulta .= "&codSerie=".$this->getRequestParameter('codSerie');
	}
	
	if($this->getRequestParameter('descripcion')){
		$c->add(SeriePeer::DESCRIPCION, '%'.$this->getRequestParameter('descripcion').'%',Criteria::LIKE);
		$parametros_consulta .= "&descripcion=".$this->getRequestParameter('descripcion');
	}
	//////////////////////////////////////////////////////////////////////////////////
	$c->addAscendingOrderByColumn(SeriePeer::SERIE_ID);
	//////////////////////////////////////////////////////////////////////////////////
	///////////////////  DESCRIPCION UBICACION ///////////////////////////
	$ubicacion = DependenciaPeer::retrieveByPk($this->dependencia_id);
	$this->name_dependencia = $ubicacion->getNombre();
		
	/////////////////////////////////////////////////
	
	$pager=new sfPropelPager('Serie',12);
	$pager->setCriteria($c);
	$pager->setPage($this->getRequestParameter('page',1));
	$pager->init();
	$this->pager=$pager;
	$this->filtros_consulta = $parametros_consulta;
  }

  public function executeShow()
  {
    $this->serie = SeriePeer::retrieveByPk($this->getRequestParameter('serie_id'));
    $this->forward404Unless($this->serie);
  }

  public function executeCreate()
  {
    $this->serie = new Serie();

    $this->setTemplate('edit');
  }

  public function executeEdit()
  {
    $this->serie = SeriePeer::retrieveByPk($this->getRequestParameter('serie_id'));
    $this->forward404Unless($this->serie);
  }

  public function executeUpdate()
  {
    if (!$this->getRequestParameter('serie_id'))
    {
      $serie = new Serie();
    }
    else
    {
      $serie = SeriePeer::retrieveByPk($this->getRequestParameter('serie_id'));
      $serie_anterior = $serie->copy();
      $this->forward404Unless($serie);
    }
    //****************************************************************************************************
    $descripcion = trim($this->getRequestParameter('descripcion'));
    $codigo = trim($this->getRequestParameter('codigo'));
    //$descripcion = ereg_replace("[^A-Za-z0-9 +]","",$descripcion);
	  //****************************************************************************************************
    $serie->setDependenciaId($this->getRequestParameter('dependencia_id') ? $this->getRequestParameter('dependencia_id') : null);
    $serie->setCodigo($codigo);    
    $serie->setDescripcion($descripcion);
    $serie->setEsVisible($this->getRequestParameter('es_visible') ? 1 : 0);
    $serie->save();
    //*****************************************************************************************************
    SeriePeer::guardarAuditoria($serie_anterior,$serie);
    //*****************************************************************************************************
    return $this->redirect($this->getRequest()->getScriptName().'/serie/show?serie_id='.$serie->getSerieId().'&dependencia_id='.$this->getRequestParameter('dependencia_id'));
  }

  public function executeValidate()
  {
  	$serie = SeriePeer::retrieveByPK($this->getRequestParameter('serie_id'));
    $serie_anterior = $serie->copy();
    //******************************************************************************************
    $serie->setEsVisible(empty($serie->getEsVisible()) ? 1 : 0);
    $serie->save();
    //******************************************************************************************
    SeriePeer::guardarAuditoria($serie_anterior,$serie);
    //******************************************************************************************
    $this->serie = $serie;
  	$this->forward404Unless($serie);
  }

  public function executeDelete()
  {
    $serie = SeriePeer::retrieveByPk($this->getRequestParameter('serie_id'));

    $this->forward404Unless($serie);

    $serie->delete();

    //return $this->redirect($this->getRequest()->getScriptName().'/serie/list?dependencia_id='.$this->getRequestParameter('dependencia_id'));
  }
}
